const fs = require('node:fs');
const assert = require('node:assert/strict');
const p = '.prospec/eval-suite-count';
const resultsPath = '.prospec/eval-suite-results.json';
fs.writeFileSync(p, String(Number(fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : 0) + 1));
const results = fs.existsSync(resultsPath) ? JSON.parse(fs.readFileSync(resultsPath, 'utf8')) : [];
results.push(null);
fs.writeFileSync(resultsPath, JSON.stringify(results));
let code = 0;
try { assert.equal(require('./src/value.cjs')(), 42); } catch { code = 1; }
results[results.length - 1] = code;
fs.writeFileSync(resultsPath, JSON.stringify(results));
process.exitCode = code;
